{
  "items": [
    {
      "name": "MvPolynomial.pderiv_rename",
      "module_name": "Mathlib.Algebra.MvPolynomial.PDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type v} [inst : CommSemiring R] {τ : Type u_1} {f : σ → τ},\n  Function.Injective f →\n    ∀ (x : σ) (p : MvPolynomial σ R),\n      (MvPolynomial.pderiv (f x)) ((MvPolynomial.rename f) p) = (MvPolynomial.rename f) ((MvPolynomial.pderiv x) p)"
    },
    {
      "name": "MvPolynomial.bind₁_rename",
      "module_name": "Mathlib.Algebra.MvPolynomial.Monad",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} [inst : CommSemiring R] {υ : Type u_6} (f : τ → MvPolynomial υ R)\n  (g : σ → τ) (φ : MvPolynomial σ R),\n  (MvPolynomial.bind₁ f) ((MvPolynomial.rename g) φ) = (MvPolynomial.bind₁ (f ∘ g)) φ"
    },
    {
      "name": "MvPolynomial.rename_bind₁",
      "module_name": "Mathlib.Algebra.MvPolynomial.Monad",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} [inst : CommSemiring R] {υ : Type u_6} (f : σ → MvPolynomial τ R)\n  (g : τ → υ) (φ : MvPolynomial σ R),\n  (MvPolynomial.rename g) ((MvPolynomial.bind₁ f) φ) = (MvPolynomial.bind₁ fun i => (MvPolynomial.rename g) (f i)) φ"
    },
    {
      "name": "MvPolynomial.IsHomogeneous.rename_isHomogeneous_iff",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} [inst : CommSemiring R] {φ : MvPolynomial σ R} {n : ℕ} {f : σ → τ},\n  Function.Injective f → (((MvPolynomial.rename f) φ).IsHomogeneous n ↔ φ.IsHomogeneous n)"
    },
    {
      "name": "MvPolynomial.rename",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  {τ : Type u_2} → {R : Type u_4} → [inst : CommSemiring R] → (σ → τ) → MvPolynomial σ R →ₐ[R] MvPolynomial τ R"
    }
  ]
}
